command:
$ErrorActionPreference='Stop'
$repo='tngkrwlsmd/universal-agent-docs'
$tag='v0.6.3'
$source='b8909a5550168d38e6abbe8df9b504f0759f660c'
$expectedA='d0011a69f6bc209931eeb0d60fb9d278e9ce7c89'
$root=$env:FLYEXPLORER_CANONICAL_CHECKOUT
if([string]::IsNullOrWhiteSpace($root) -or !(Test-Path -LiteralPath $root -PathType Container)){throw 'Canonical checkout unavailable'}
Set-Location -LiteralPath $root
& git fetch origin --no-tags
if($LASTEXITCODE -ne 0){throw 'A fetch failed'}
$branch=(& git symbolic-ref --short HEAD).Trim()
$local=(& git rev-parse HEAD).Trim()
$remoteHead=(& git rev-parse refs/remotes/origin/main).Trim()
if($branch -ne 'main' -or $local -ne $expectedA -or $remoteHead -ne $expectedA){throw ('A baseline moved: '+$branch+' '+$local+' '+$remoteHead)}
$dirty=@(& git status --porcelain --untracked-files=normal)
if($dirty.Count -gt 0){throw ('Canonical checkout has existing changes: '+($dirty -join '; '))}
$tagSha=(& gh api "repos/$repo/git/ref/tags/$tag" --jq '.object.sha')
if($LASTEXITCODE -ne 0 -or $tagSha.Trim() -ne $source){throw 'B release tag/source mismatch'}
$releaseJson=(& gh api "repos/$repo/releases/tags/$tag" | Out-String)
if($LASTEXITCODE -ne 0){throw 'B release lookup failed'}
$release=$releaseJson | ConvertFrom-Json
if($release.tag_name -ne $tag -or !$release.immutable -or $release.target_commitish -ne $source){throw 'B immutable release identity invalid'}
$asset=@($release.assets | Where-Object { $_.name -eq 'universal-agent-docs-consumer.zip' })
if($asset.Count -ne 1 -or $asset[0].digest -notmatch '^sha256:[0-9a-f]{64}$'){throw 'B asset digest unavailable'}
$temp=Join-Path $env:TEMP ('fly-policy-sync-'+[Guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $temp -Force | Out-Null
try {
 & gh release download $tag --repo $repo --dir $temp --pattern 'universal-agent-docs-consumer*'
 if($LASTEXITCODE -ne 0){throw 'Consumer release download failed'}
 $zip=Join-Path $temp 'universal-agent-docs-consumer.zip'
 $checksum=Join-Path $temp 'universal-agent-docs-consumer.sha256'
 $manifest=Join-Path $temp 'universal-agent-docs-consumer.release.json'
 foreach($p in @($zip,$checksum,$manifest)){if(!(Test-Path -LiteralPath $p -PathType Leaf)){throw ('Missing release asset: '+$p)}}
 $actualHash=(Get-FileHash -LiteralPath $zip -Algorithm SHA256).Hash.ToLowerInvariant()
 $detached=((Get-Content -LiteralPath $checksum -TotalCount 1).Trim() -split '\s+')[0].ToLowerInvariant()
 if($actualHash -ne $detached -or ('sha256:'+$actualHash) -ne $asset[0].digest){throw 'Consumer ZIP digest mismatch'}
 Write-Output ('RELEASE_DIGEST=PASS sha256:'+$actualHash)
 $unpack=Join-Path $temp 'unpacked'
 New-Item -ItemType Directory -Path $unpack -Force | Out-Null
 & python -m zipfile -e $zip $unpack
 if($LASTEXITCODE -ne 0){throw 'Consumer ZIP extraction failed'}
 $bundle=Join-Path $unpack 'universal-agent-docs-consumer\.agent-policy'
 $contractPath=Join-Path $bundle 'POLICY_CONTRACT.json'
 if(!(Test-Path -LiteralPath $contractPath)){throw 'Consumer bundle layout unexpected'}
 $contract=(Get-Content -Raw -Encoding UTF8 -LiteralPath $contractPath | ConvertFrom-Json)
 $expected=@($contract.distribution.required_files | ForEach-Object { [string]$_ } | Sort-Object)
 $real=@(Get-ChildItem -LiteralPath $bundle -Recurse -File | ForEach-Object { $_.FullName.Substring($bundle.Length+1).Replace('\','/') } | Sort-Object)
 $bundleDelta=@(Compare-Object -ReferenceObject $expected -DifferenceObject $real)
 if($bundleDelta.Count -ne 0){throw ('Consumer bundle file set mismatch: '+($bundleDelta | Out-String))}
 $old=@(& git ls-files -- .agent-policy/ | ForEach-Object { $_.Substring('.agent-policy/'.Length) })
 if($LASTEXITCODE -ne 0){throw 'Could not inspect current vendor files'}
 $extras=@($old | Where-Object { $_ -ne 'PROJECT.md' -and $_ -notin $expected })
 if($extras.Count -gt 0){throw ('Unrecognized tracked vendor files: '+($extras -join ','))}
 $projectPath=Join-Path $root '.agent-policy\PROJECT.md'
 $projectText=[IO.File]::ReadAllText($projectPath)
 $prior='bafb40f55dcb6aa15f432b391ba5487b87759e0e'
 if(!$projectText.Contains($prior)){throw 'Project-owned policy provenance changed'}
 foreach($rel in $expected){
  if($rel -eq 'PROJECT.md'){continue}
  $from=Join-Path $bundle ($rel.Replace('/','\'))
  $to=Join-Path (Join-Path $root '.agent-policy') ($rel.Replace('/','\'))
  $parent=Split-Path -Parent $to
  if(!(Test-Path -LiteralPath $parent)){New-Item -ItemType Directory -Path $parent -Force | Out-Null}
  Copy-Item -LiteralPath $from -Destination $to -Force
 }
 $projectText=$projectText.Replace($prior,$source+' (release '+$tag+')')
 [IO.File]::WriteAllText($projectPath,$projectText,(New-Object System.Text.UTF8Encoding($false)))
 Write-Output ('VENDOR_CORE_FILES='+($expected.Count-1)+' PROJECT_PRESERVED=YES')
 $log=Join-Path $temp 'policy-validation.log'
 & cmd.exe /d /c 'test.bat policy' *> $log
 $checkExit=$LASTEXITCODE
 if($checkExit -ne 0){ Get-Content -LiteralPath $log -Tail 45; throw ('A policy validation failed exit='+$checkExit) }
 Get-Content -LiteralPath $log -Tail 8
 & git diff --check
 if($LASTEXITCODE -ne 0){throw 'A diff whitespace check failed'}
 & git add -- .agent-policy
 if($LASTEXITCODE -ne 0){throw 'A policy stage failed'}
 & git diff --cached --check
 if($LASTEXITCODE -ne 0){throw 'Staged diff check failed'}
 $staged=@(& git diff --cached --name-only)
 if($staged.Count -eq 0 -or @($staged | Where-Object { $_ -notlike '.agent-policy/*' }).Count -ne 0){throw 'Staged scope invalid'}
 Write-Output ('A_POLICY_STAGED_FILES='+$staged.Count)
 & git fetch origin --no-tags
 if($LASTEXITCODE -ne 0){throw 'Pre-push fetch failed'}
 if((& git rev-parse refs/remotes/origin/main).Trim() -ne $expectedA){throw 'A main moved before push; preserve pending changes'}
 & git commit -m ('chore(policy): sync verified universal-agent-docs '+$tag)
 if($LASTEXITCODE -ne 0){throw 'A commit failed'}
 $commit=(& git rev-parse HEAD).Trim()
 & git push origin HEAD:main
 if($LASTEXITCODE -ne 0){throw 'A push failed; reconcile remote state before retry'}
 & git fetch origin --no-tags
 if($LASTEXITCODE -ne 0 -or (& git rev-parse refs/remotes/origin/main).Trim() -ne $commit){throw 'A main postcondition failed'}
 $remaining=@(& git status --porcelain)
 if($remaining.Count -ne 0){throw 'A checkout not clean after synchronization'}
 Write-Output ('A_POLICY_SYNC=PASS SOURCE='+$tag+'@'+$source+' A_COMMIT='+$commit)
} finally { Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue }
